// Offline support for the Guatemala guide. Generated by build_site.py.
const VERSION = "6.10.0-c1329ce38c";
const CORE = "core-" + VERSION;      // latest page, assets, maps, photos
const RUNTIME = "runtime-v1";        // older versions, CDN code, extras
const PRECACHE = [
  "./",
  "assets/site.css",
  "assets/site.js",
  "assets/icon-192.png",
  "assets/icon-512.png",
  "manifest.webmanifest",
  "trip.ics",
  "maps/web/chart-08-altitude.jpg",
  "maps/web/map-01-overview.jpg",
  "maps/web/map-02-highlands.jpg",
  "maps/web/map-03-north.jpg",
  "maps/web/map-04-antigua.jpg",
  "maps/web/map-04-atitlan.jpg",
  "maps/web/map-05-xela.jpg",
  "maps/web/map-06-peten.jpg",
  "maps/web/map-07-izabal.jpg"
];       // same-origin, relative to scope
const PHOTOS = [
  "https://commons.wikimedia.org/wiki/Special:FilePath/Arco_de_Santa_Catalina_Antigua_Guatemala_edit2.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Chichicastenango_market_2009.JPG?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Iglesia_de_Santo_Tom%C3%A1s_2009.JPG?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Isla_de_Flores_desde_el_Lago_Pet%C3%A9n_Itz%C3%A1.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Lago_Atitlan%2C_seen_from_San_Marcos.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Lago_Pet%C3%A9n_Itz%C3%A1_cerca_de_El_Remate%2C_Pet%C3%A9n%2C_Guatemala_-_panoramio.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Semuc_Champey%2C_Guatemala.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Tajumulco_Volcano.JPG?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Tikal-Plaza-Mayor-Panorama.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Tikal_Temple_I.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/View_from_Volcano_Pacaya%2C_Guatemala.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Volcan-San-Pedro-Panorama.JPG?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Volcan_y_laguna_chicabal.jpg?width=1280",
  "https://commons.wikimedia.org/wiki/Special:FilePath/Yaxhatemplo216.jpg?width=900"
];           // cross-origin images on the page
const MERMAID = "https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.esm.min.mjs";

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CORE);
    await cache.addAll(PRECACHE);
    // chart code from the CDN: best effort, needs CORS for a module
    try {
      const res = await fetch(MERMAID, { mode: "cors" });
      if (res.ok) await cache.put(MERMAID, res);
    } catch (e) { /* the chart just won't draw offline */ }
    // photos: best effort, opaque responses are fine for <img>
    await Promise.all(PHOTOS.map(async (url) => {
      try {
        const res = await fetch(url, { mode: "no-cors" });
        await cache.put(url, res);
      } catch (e) { /* keep going */ }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith("core-") && key !== CORE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

async function fromCache(request) {
  return (await caches.match(request, { ignoreSearch: true }))
      || (await caches.match(request.url.split("#")[0], { ignoreSearch: true }));
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  const sameOrigin = url.origin === self.location.origin;

  // pages: network first (3 s), then the cached copy
  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        const res = await Promise.race([
          fetch(request),
          new Promise((_, reject) => setTimeout(() => reject("slow"), 3000)),
        ]);
        if (res.ok) {
          const cache = await caches.open(sameOrigin && url.pathname.match(/\/v\d/) ? RUNTIME : CORE);
          cache.put(request.url.split("?")[0], res.clone());
        }
        return res;
      } catch (e) {
        return (await fromCache(request))
            || (await caches.match(self.registration.scope))
            || Response.error();
      }
    })());
    return;
  }

  // everything else: cache first, fill the cache on the way
  event.respondWith((async () => {
    const hit = await fromCache(request);
    if (hit) return hit;
    try {
      const res = await fetch(request);
      if (res.ok || res.type === "opaque") {
        (await caches.open(RUNTIME)).put(request, res.clone());
      }
      return res;
    } catch (e) {
      return Response.error();
    }
  })());
});
